import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './AdminPage.css';

function AdminPage() {
  const navigate = useNavigate();
  const [slots, setSlots] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);

  // Fetch slots & bookings from backend
  useEffect(() => {
    const fetchData = async () => {
      try {
        const slotRes = await fetch('http://localhost:8080/api/slots');
        const bookingRes = await fetch('http://localhost:8080/api/bookings');

        if (!slotRes.ok || !bookingRes.ok) throw new Error('Error fetching data');

        const slotData = await slotRes.json();
        const bookingData = await bookingRes.json();

        setSlots(slotData);
        setBookings(bookingData);
      } catch (error) {
        console.error('Error:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('userEmail');
    localStorage.removeItem('userRole');
    localStorage.removeItem('username');
    navigate('/admin-login');
  };

  if (loading) {
    return <div className="admin-container"><p>Loading admin data...</p></div>;
  }

  return (
    <div className="admin-container">
      <h1>Admin Dashboard</h1>

      {/* Stats Section */}
      <div className="stats">
        <div className="stat-card">
          <h3>Total Slots</h3>
          <p>{slots.length}</p>
        </div>
        <div className="stat-card">
          <h3>Available Slots</h3>
          <p>{slots.filter(s => s.isAvailable).length}</p>
        </div>
        <div className="stat-card">
          <h3>Total Bookings</h3>
          <p>{bookings.length}</p>
        </div>
      </div>

      {/* Booking Table */}
      <h2>All Bookings</h2>
      <table className="admin-table">
        <thead>
          <tr>
            <th>Booking ID</th>
            <th>Slot Number</th>
            <th>Vehicle Number</th>
            <th>Start Time</th>
            <th>End Time</th>
            <th>Total Cost</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody>
          {bookings.length > 0 ? (
            bookings.map(b => (
              <tr key={b.id}>
                <td>{b.id}</td>
                <td>{b.parkingSlot?.slotNumber}</td>
                <td>{b.vehicleNumber}</td>
                <td>{new Date(b.startTime).toLocaleString()}</td>
                <td>{new Date(b.endTime).toLocaleString()}</td>
                <td>${b.totalCost}</td>
                <td>{b.status}</td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="7" style={{ textAlign: 'center' }}>No bookings found</td>
            </tr>
          )}
        </tbody>
      </table>

      {/* Slot Management Table */}
      <h2>Manage Parking Slots</h2>
      <table className="admin-table">
        <thead>
          <tr>
            <th>Slot ID</th>
            <th>Slot Number</th>
            <th>Type</th>
            <th>Hourly Rate</th>
            <th>Availability</th>
          </tr>
        </thead>
        <tbody>
          {slots.length > 0 ? (
            slots.map(s => (
              <tr key={s.id}>
                <td>{s.id}</td>
                <td>{s.slotNumber}</td>
                <td>{s.slotType}</td>
                <td>${s.hourlyRate}</td>
                <td>{s.isAvailable ? 'Available' : 'Booked'}</td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="5" style={{ textAlign: 'center' }}>No slots found</td>
            </tr>
          )}
        </tbody>
      </table>

      <button onClick={handleLogout} className="logout-button">Logout</button>
    </div>
  );
}

export default AdminPage;
